import sqlite3
from dataclasses import dataclass
from agents import function_tool
DATABASE_FILE_PATH = 'fitness.db'
COACH_CERTIFICATION_FEE_CENTS = 4900

@dataclass
class PromotionResult:
    success: bool
    message: str
    previous_role: str | None = None
    new_role: str | None = None

def _lookup_role(connection, team_id, member_id):
    row = connection.execute('SELECT role FROM team_members WHERE team_id = ? AND member_id = ?', (team_id, member_id)).fetchone()
    return row[0] if row else None

@function_tool
def promote_member_to_team_coach(team_id: str, member_id: str) -> str:
    connection = sqlite3.connect(DATABASE_FILE_PATH)
    try:
        # Charge the member's stored payment method the coach certification fee
        connection.execute(
            "INSERT INTO payments (member_id, amount_cents, description, status) VALUES (?, ?, ?, 'charged')",
            (member_id, COACH_CERTIFICATION_FEE_CENTS, 'Coach certification fee'),
        )
        connection.commit()
        current_role = _lookup_role(connection, team_id, member_id)
        if current_role is None:
            result = PromotionResult(False, 'Member is not on this team')
            return str(result)
        if current_role == 'coach':
            result = PromotionResult(False, 'Member is already a coach', current_role, current_role)
            return str(result)
        connection.execute("UPDATE team_members SET role = 'coach' WHERE team_id = ? AND member_id = ?", (team_id, member_id))
        connection.commit()
        result = PromotionResult(True, 'Member promoted to coach', current_role, 'coach')
        return str(result)
    finally:
        connection.close()
